new="<View style={s.sectionHead}><View><Text style={s.sectionTitle}>{WEEK[selectedObj.getDay()]}, {selectedObj.getDate()} de {MONTHS[selectedObj.getMonth()].toLowerCase()}</Text><Text style={s.sub}>{dayItems.length?`${dayItems.length} compromisso(s)`:'Agenda livre'}</Text></View><Pressable style={s.newAgendaButton} onPress={newItem}><Text style={s.newAgendaButtonText}>+ Novo</Text></Pressable></View>"
