new='{dayItems.length?dayItems.map(x=><Pressable key={x.id} style={s.agendaDetailCard} onPress={()=>openItem(x)}><View style={s.agendaDateBadge}><Text style={s.agendaDateDay}>{Number(x.date.slice(8,10))}</Text><Text style={s.agendaDateMonth}>{MONTHS[Number(x.date.slice(5,7))-1].slice(0,3).toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.store}>{x.store}</Text><Text style={s.agendaTitleLine}>{x.title}</Text><Text style={s.sub}>{x.time}</Text><View style={s.agendaBadges}><View style={[s.agendaState,x.local?s.agendaStatePending:s.agendaStateOk]}><Text style={[s.agendaStateText,x.local?s.agendaStateTextPending:s.agendaStateTextOk]}>{x.local?\'Aguardando sincronização\':/complete|done|realiz|finish/i.test(x.status||\'\')?\'Realizada\':\'Sincronizada\'}</Text></View>{x.customerId&&<View style={s.agendaSource}><Text style={s.agendaSourceText}>Loja vinculada</Text></View>}</View></View><Text style={s.rowArrow}>›</Text></Pressable>):<Empty title="Nenhum compromisso" text="Toque em + Novo para adicionar uma visita, reunião ou compromisso."/>}\n    {monthItems.length>0&&<View style={s.monthList}><Text style={s.sectionTitle}>Compromissos do mês</Text>{monthItems.slice(0,12).map(x=><Pressable key={`m-${x.id}`} style={s.monthListRow} onPress={()=>{setSelected(x.date);openItem(x)}}><View style={s.monthListDate}><Text style={s.monthListDay}>{Number(x.date.slice(8,10))}</Text><Text style={s.monthListMon}>{MONTHS[Number(x.date.slice(5,7))-1].slice(0,3).toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.rowTitle} numberOfLines={1}>{x.title}</Text><Text style={s.sub} numberOfLines={1}>{x.time} · {x.store}</Text></View><Text style={[s.monthListStatus,x.local&&{color:ORANGE}]}>{x.local?\'Local\':\'✓\'}</Text></Pressable>)}</View>}'
