reports=r'''function Reports({ data, local }: { data: BootstrapData | null; local: LocalState }) {
  const perf=data?.performance;
  const [period,setPeriod]=useState<'day'|'week'|'month'>('month');
  const start=useMemo(()=>{const d=new Date();d.setHours(0,0,0,0);if(period==='week')d.setDate(d.getDate()-6);if(period==='month')d.setDate(1);return d.getTime()},[period]);
  const end=Date.now();
  const localKmRecords=local.km.filter(x=>{const t=new Date(x.createdAt).getTime();return t>=start&&t<=end});
  const localTrips=local.trips.filter(x=>x.finishedAt>=start&&x.finishedAt<=end);
  const localVisits=local.visits.filter(x=>{const t=new Date(x.updatedAt).getTime();return t>=start&&t<=end});
  const localKm=localKmRecords.reduce((n,x)=>n+x.total,0),tripKm=localTrips.reduce((n,x)=>n+x.distanceMeters/1000,0),tripMinutes=localTrips.reduce((n,x)=>n+x.elapsedMs/60000,0);
  const periodLabel=period==='day'?'Hoje':period==='week'?'Últimos 7 dias':'Este mês';
  const share=async()=>{const text=[`Movvant Enterprise — visão gerencial`,`Período local: ${periodLabel}`,`KM registrado: ${localKm.toFixed(1)} km`,`Deslocamentos: ${localTrips.length}`,`Tempo em deslocamento: ${Math.round(tripMinutes)} min`,`Visitas locais: ${localVisits.length}`,`Visitas remotas 30d: ${num(perf?.visits_30d)}`,`Receita remota 30d: ${money(perf?.revenue_30d)}`].join('\n');await Share.share({message:text,title:'Visão gerencial Movvant'});};
  return <ScrollView contentContainerStyle={s.content}>
    <View style={s.managementHero}><Text style={s.agendaEyebrow}>VISÃO GERENCIAL</Text><Text style={s.managementTitle}>Operação em números</Text><Text style={s.managementText}>Acompanhe deslocamentos, KM, visitas e indicadores comerciais do período.</Text></View>
    <View style={s.periodTabs}><Pressable style={[s.periodTab,period==='day'&&s.periodTabOn]} onPress={()=>setPeriod('day')}><Text style={[s.periodTabText,period==='day'&&s.periodTabTextOn]}>Dia</Text></Pressable><Pressable style={[s.periodTab,period==='week'&&s.periodTabOn]} onPress={()=>setPeriod('week')}><Text style={[s.periodTabText,period==='week'&&s.periodTabTextOn]}>Semana</Text></Pressable><Pressable style={[s.periodTab,period==='month'&&s.periodTabOn]} onPress={()=>setPeriod('month')}><Text style={[s.periodTabText,period==='month'&&s.periodTabTextOn]}>Mês</Text></Pressable></View>
    <View style={s.periodCard}><Text style={s.periodLabel}>PERÍODO SELECIONADO</Text><Text style={s.periodValue}>{periodLabel}</Text><Text style={s.sub}>{new Date(start).toLocaleDateString('pt-BR')} → {new Date(end).toLocaleDateString('pt-BR')}</Text></View>
    <View style={s.reportGrid}><View style={s.reportCard}><Text style={s.reportKicker}>KM NO PERÍODO</Text><Text style={s.reportValue}>{localKm.toFixed(1)} km</Text><Text style={s.metricLabel}>{localKmRecords.length} lançamento(s)</Text></View><View style={s.reportCard}><Text style={s.reportKicker}>DESLOCAMENTOS</Text><Text style={s.reportValue}>{localTrips.length}</Text><Text style={s.metricLabel}>{tripKm.toFixed(1)} km rastreados</Text></View><View style={s.reportCard}><Text style={s.reportKicker}>TEMPO EM ROTA</Text><Text style={s.reportValue}>{Math.round(tripMinutes)} min</Text><Text style={s.metricLabel}>Tempo rastreado</Text></View><View style={s.reportCard}><Text style={s.reportKicker}>VISITAS</Text><Text style={s.reportValue}>{localVisits.length}</Text><Text style={s.metricLabel}>Movimentações locais</Text></View></View>
    <View style={s.reportWide}><Text style={s.reportWideTitle}>Indicadores empresariais · 30 dias</Text><Text style={s.reportWideSub}>Dados consolidados disponíveis na base empresarial.</Text><View style={s.reportLine}><Text style={s.sub}>Visitas</Text><Text style={s.reportLineValue}>{num(perf?.visits_30d)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Visitas validadas</Text><Text style={s.reportLineValue}>{num(perf?.validated_visits_30d)}</Text></View><View style={s.reportLine}><Text style={s.sub}>KM remoto</Text><Text style={s.reportLineValue}>{num(perf?.actual_km_30d).toFixed(1)} km</Text></View><View style={s.reportLine}><Text style={s.sub}>Aderência</Text><Text style={s.reportLineValue}>{num(perf?.avg_adherence_pct).toFixed(0)}%</Text></View><View style={s.reportLine}><Text style={s.sub}>Pedidos</Text><Text style={s.reportLineValue}>{num(perf?.orders_30d)}</Text></View><View style={s.reportLine}><Text style={s.sub}>Receita</Text><Text style={s.reportLineValue}>{money(perf?.revenue_30d)}</Text></View></View>
    <View style={s.analysisCard}><Text style={s.reportWideTitle}>Leitura operacional</Text><Text style={s.analysisText}>{localTrips.length===0?'Sem deslocamentos registrados neste período.':'Há deslocamentos registrados no período selecionado.'}</Text><Text style={s.analysisText}>{localKmRecords.length===0?'Nenhum lançamento manual de KM neste período.':`${localKmRecords.length} lançamento(s) de KM somando ${localKm.toFixed(1)} km.`}</Text><Text style={s.analysisText}>{localVisits.length===0?'Nenhuma movimentação local de visita neste período.':`${localVisits.length} movimentação(ões) de visita registradas localmente.`}</Text></View>
    <Pressable style={s.primary} onPress={share}><Text style={s.primaryText}>Compartilhar visão gerencial</Text></Pressable>
    {!perf&&<Empty title="Indicadores remotos ainda indisponíveis" text="Os números locais continuam funcionando; a parte empresarial será preenchida quando a base liberar os indicadores."/>}
  </ScrollView>;
}
'''
s=s[:r0]+reports+s[r1:]

