styles="  agendaHero:{backgroundColor:'#fff',borderWidth:1,borderColor:BORDER,borderRadius:24,padding:18},agendaEyebrow:{fontSize:9,letterSpacing:1.8,color:BLUE,fontWeight:'900'},agendaHeroTitle:{fontSize:22,fontWeight:'900',color:NAVY,marginTop:5},agendaHeroText:{fontSize:11,color:MUTED,lineHeight:17,marginTop:5},agendaSummary:{flexDirection:'row',gap:8},agendaSummaryItem:{flex:1,backgroundColor:'#fff',borderWidth:1,borderColor:BORDER,borderRadius:16,padding:12},agendaSummaryValue:{fontSize:20,fontWeight:'900',color:NAVY},agendaSummaryLabel:{fontSize:9,color:MUTED,marginTop:3},monthNav:{width:42,height:42,borderRadius:13,borderWidth:1,borderColor:BORDER,alignItems:'center',justifyContent:'center'},monthSub:{fontSize:9,color:MUTED,textAlign:'center',marginTop:2},newAgendaButton:{minHeight:40,paddingHorizontal:14,borderRadius:12,borderWidth:1,borderColor:NAVY,alignItems:'center',justifyContent:'center'},newAgendaButtonText:{fontSize:11,fontWeight:'900',color:NAVY},agendaDetailCard:{minHeight:112,backgroundColor:'#fff',borderWidth:1,borderColor:BORDER,borderRadius:19,padding:13,flexDirection:'row',alignItems:'center',gap:12},agendaDateBadge:{width:52,height:64,borderRadius:14,backgroundColor:'#F2F5F9',alignItems:'center',justifyContent:'center'},agendaDateDay:{fontSize:20,fontWeight:'900',color:NAVY},agendaDateMonth:{fontSize:8,fontWeight:'800',color:MUTED,marginTop:2},agendaTitleLine:{fontSize:11,fontWeight:'800',color:TEXT,marginTop:2},agendaBadges:{flexDirection:'row',flexWrap:'wrap',gap:6,marginTop:7},agendaState:{paddingHorizontal:9,paddingVertical:5,borderRadius:10},agendaStateOk:{backgroundColor:'#E8F7F0'},agendaStatePending:{backgroundColor:'#FFF3E5'},agendaStateText:{fontSize:8,fontWeight:'900'},agendaStateTextOk:{color:GREEN},agendaStateTextPending:{color:ORANGE},agendaSource:{paddingHorizontal:9,paddingVertical:5,borderRadius:10,backgroundColor:'#EAF2FE'},agendaSourceText:{fontSize:8,fontWeight:'900',color:BLUE},monthList:{backgroundColor:'#fff',borderWidth:1,borderColor:BORDER,borderRadius:20,padding:14,gap:8},monthListRow:{minHeight:62,flexDirection:'row',alignItems:'center',gap:10,borderBottomWidth:1,borderBottomColor:'#EEF2F5'},monthListDate:{width:42,alignItems:'center'},monthListDay:{fontSize:16,fontWeight:'900',color:NAVY},monthListMon:{fontSize:7,fontWeight:'800',color:MUTED},monthListStatus:{fontSize:11,fontWeight:'900',color:GREEN},managementHero:{backgroundColor:NAVY,borderRadius:24,padding:20},managementTitle:{fontSize:24,fontWeight:'900',color:'#fff',marginTop:5},managementText:{fontSize:11,color:'#D0DCE6',lineHeight:17,marginTop:5},periodTabs:{backgroundColor:'#E9EEF4',borderRadius:18,padding:4,flexDirection:'row'},periodTab:{flex:1,minHeight:46,borderRadius:14,alignItems:'center',justifyContent:'center'},periodTabOn:{backgroundColor:NAVY,elevation:2},periodTabText:{fontSize:11,fontWeight:'800',color:MUTED},periodTabTextOn:{color:'#fff'},periodCard:{backgroundColor:'#fff',borderWidth:1,borderColor:BORDER,borderRadius:18,padding:15},periodLabel:{fontSize:9,fontWeight:'900',letterSpacing:1,color:MUTED},periodValue:{fontSize:18,fontWeight:'900',color:NAVY,marginTop:4},reportKicker:{fontSize:9,fontWeight:'900',letterSpacing:.8,color:MUTED},reportWideTitle:{fontSize:15,fontWeight:'900',color:NAVY},reportWideSub:{fontSize:10,color:MUTED,marginBottom:4},analysisCard:{backgroundColor:'#fff',borderWidth:1,borderColor:BORDER,borderRadius:18,padding:15,gap:8},analysisText:{fontSize:11,color:TEXT,lineHeight:17},\n"
